arguments.command:
cat > tests/lag_alert_test.sh <<'EOF'
#!/bin/bash
fail=0
out=$(NOW=$(date -u -d "2026-11-03T12:00:00Z" +%s) bash ops/lag-alert.sh)
# data/readings/latest.csv の最新時刻から十分遅れている想定
echo "$out" | grep -q '最大 6 時間' || { echo "lag-alert: 最大 6 時間 の案内がない"; fail=1; }
echo "$out" | grep -q '24 時間' && { echo "lag-alert: 24 時間が残っている"; fail=1; }
exit $fail
EOF
tail -1 data/readings/latest.csv; bash tests/lag_alert_test.sh; echo rc=$?

